RSpec.describe "Timekeeping handoff admission" do
  include_context "timekeeping entry writes without transactional fixtures"

  let(:admission_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => admission_token
    ) { example.run }
  end

  before { Timekeeping::Admission.ensure_initial! }

  it "fences and then admits generation 2 on the real admission row" do
    headers = { "Authorization" => "Bearer #{admission_token}", "CONTENT_TYPE" => "application/json" }

    # "Admission: fence and admit through `Timekeeping::Admission.fence!` and `Timekeeping::Admission.admit!`, from the admission-fence work this depends on."
    post "/internal/v1/handoff/admission/fence", headers: headers
    expect([response.status, response.parsed_body]).to eq([200, { "generation" => nil }])
    expect(Timekeeping::Admission.current.generation).to be_nil

    post "/internal/v1/handoff/admission/admit", params: { generation: 2 }.to_json, headers: headers
    expect([response.status, response.parsed_body]).to eq([200, { "generation" => 2 }])
    expect(Timekeeping::Admission.current.generation).to eq(2)

    post "/internal/v1/handoff/admission/admit", params: { generation: 0 }.to_json, headers: headers
    expect([response.status, response.parsed_body]).to eq([400, { "reason" => "invalid_request" }])
    expect(Timekeeping::Admission.current.generation).to eq(2)
  end
end

RSpec.describe "Timekeeping handoff route refusals" do
  let(:refusal_token) { "service-#{SecureRandom.hex(24)}" }

  around do |example|
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => refusal_token
    ) { example.run }
  end

  before { Timekeeping::Admission.ensure_initial! }

  it "refuses an admin user token on every handoff route and changes no admission or entry row" do
    admin = mint_token({ sub: 7, company_id: 1, role: "admin" })
    handoff_routes = [
      [:get, "/internal/v1/handoff/checkpoint", nil],
      [:put, "/internal/v1/handoff/checkpoint", "{}"],
      [:post, "/internal/v1/handoff/entry_id_sequence", { above: 5 }.to_json],
      [:get, "/internal/v1/handoff/outbox_position", nil],
      [:put, "/internal/v1/handoff/correction_snapshots", { generation: 2, version: 1, snapshots: [] }.to_json],
      [:post, "/internal/v1/handoff/admission/fence", nil],
      [:post, "/internal/v1/handoff/admission/admit", { generation: 9 }.to_json]
    ]
    generation_before = Timekeeping::Admission.current.generation

    # "Every handoff endpoint refuses a caller without service credentials"
    handoff_routes.each do |verb, path, body|
      [{ "Authorization" => "Bearer #{admin}" }, {}, { "Authorization" => "Bearer #{refusal_token}x" }].each do |auth|
        send(verb, path, params: body, headers: auth.merge("CONTENT_TYPE" => "application/json"))
        expect([response.status, response.parsed_body]).to eq([401, { "reason" => "unauthorized" }]), "#{verb} #{path}"
      end
    end
    expect(Timekeeping::Admission.current.generation).to eq(generation_before)
    expect(Entry.count).to eq(0)
  end
end
